inline const std::vector<Entry>& StringsFor(const std::wstring& lang) {
    if (lang == L"cat") { return Strings_cat(); }
    if (lang == L"en") { return Strings_en(); }
    if (lang == L"es") { return Strings_es(); }
    if (lang == L"fr") { return Strings_fr(); }
    if (lang == L"pl") { return Strings_pl(); }
    if (lang == L"tr") { return Strings_tr(); }
    return Strings_en();
}

